    "questionAr": "في لحظة معينة، كانت العجلة المماسية لجسيم $a_t = 60\\text{ م/ث}^2$ والعجلة العمودية $a_n = 80\\text{ م/ث}^2$. احسب معيار العجلة الكلية $\\|\\vec{a}\\|$.",
