    "titleEn": "Center of Curvature of Parabola at Vertex #1",
    "titleAr": "مركز دائرة الانحناء لقطع مكافئ عند الرأس رقم 1",
    "difficulty": "hots",
    "questionEn": "Find the exact coordinates of the center of curvature $C$ for the parabola $y = 1x^2$ at its vertex $(0, 0)$.",
    "questionAr": "أوجد الإحداثيات الدقيقة لمركز دائرة الانحناء $C$ للقطع المكافئ $y = 1x^2$ عند رأسه $(0, 0)$.",
    "optionsEn": [
      "$(0, \\frac{1}{2})$",
      "$(0, \\frac{1}{3})$",
      "$(0, \\frac{1}{4})$",
      "$(0, \\frac{1}{5})$"
    ],
    "optionsAr": [
      "$(0, \\frac{1}{2})$",
      "$(0, \\frac{1}{3})$",
      "$(0, \\frac{1}{4})$",
      "$(0, \\frac{1}{5})$"
    ],
    "correctAnswer": "$(0, \\frac{1}{2})$",
    "correctIndex": 0,
    "hintEn": "At vertex, y' = 0 and y'' = 2p. Radius is 1 / (2p) directed upward along the y-axis.",
    "hintAr": "عند الرأس، المشتقة الأولى صفر والمشتقة الثانية 2p. نصف القطر 1/(2p) لأعلى على محور الصادات.",
    "stepByStepSolutionEn": [
      "1. Derivatives: $y' = 2(1)x \\implies y'(0) = 0$, and $y'' = 2(1) = 2$.",
      "2. Radius of curvature: $\\rho = \\frac{1}{|y''|} = \\frac{1}{2}$.",
      "3. Normal vector points along $+y$ axis: $\\hat{N} = (0, 1)$.",
      "4. Center of curvature: $C = (0, 0) + \\rho(0, 1) = (0, \\frac{1}{2})$."
    ],
    "stepByStepSolutionAr": [
      "١. المشتقات: $y'(0) = 0$ و $y'' = 2$.",
      "٢. نصف قطر الانحناء: $\\rho = \\frac{1}{2}$.",
      "٣. متجه الوحدة العمودي يشير لأعلى على محور الصادات: $\\hat{N} = (0, 1)$.",
      "٤. إحداثيات مركز الانحناء: $C = (0, \\frac{1}{2})$."
    ],
    "teacherTipEn": "The osculating circle fits the parabola up to 2nd order at the contact point.",
    "teacherTipAr": "دائرة الانحناء اللامسة تطابق منحنى القطع المكافئ حتى الرتبة الثانية عند نقطة التماس."
